import { copyFile, mkdir } from 'node:fs/promises';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

// The web display imports JSON directly; the download is generated by the same source.
execFileSync('python3', [fileURLToPath(new URL('../../../../operations/generate_timetable.py', import.meta.url))], { stdio: 'inherit' });
await mkdir(new URL('../public/downloads/', import.meta.url), { recursive: true });
await copyFile(new URL('../../../../operations/timetable.html', import.meta.url), new URL('../public/downloads/timetable.html', import.meta.url));
